function closeModalOverlay() {
    // If the auth modal was opened from the detail modal, return to the detail modal instead of closing overlay
    if (!DOM.modalAuth.classList.contains('hidden') && State.modalDetailWasOpen && State.currentDetailCar) {
        DOM.modalAuth.classList.add('hidden');
        DOM.modalDetail.classList.remove('hidden');
        State.modalDetailWasOpen = false; // Reset the flag
        return;
    }

    DOM.modalOverlay.classList.add('hidden');
    // Hide all modal cards inside
    DOM.modalAuth.classList.add('hidden');
    DOM.modalSell.classList.add('hidden');
    DOM.modalDetail.classList.add('hidden');
    document.body.style.overflow = ""; // enable background scroll
    State.modalDetailWasOpen = false; // Reset the flag
    pendingAuthCallback = null; // Clear pending action when overlay is closed
}

