// Sign In Submit
DOM.signinForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = document.getElementById('signin-email').value;
    const password = document.getElementById('signin-password').value;

    if (State.loginUser(email, password)) {
        DOM.signinForm.reset();
        syncAuthUI();

        const detailWasOpen = State.modalDetailWasOpen;
        State.modalDetailWasOpen = false; // clear flag before close

        closeModalOverlay();
        renderListingsGrid();

        if (pendingAuthCallback) {
            const callback = pendingAuthCallback;
            pendingAuthCallback = null;
            callback();
        } else if (detailWasOpen && State.currentDetailCar) {
            openDetailModal(State.currentDetailCar);
        }
    }
});

// Sign Up Submit
DOM.signupForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = document.getElementById('signup-name').value;
    const email = document.getElementById('signup-email').value;
    const phone = document.getElementById('signup-phone').value;
    const password = document.getElementById('signup-password').value;

    if (State.registerUser(name, email, phone, password)) {
        DOM.signupForm.reset();
        syncAuthUI();

        const detailWasOpen = State.modalDetailWasOpen;
        State.modalDetailWasOpen = false; // clear flag before close

        closeModalOverlay();
        renderListingsGrid();

        if (pendingAuthCallback) {
            const callback = pendingAuthCallback;
            pendingAuthCallback = null;
            callback();
        } else if (detailWasOpen && State.currentDetailCar) {
            openDetailModal(State.currentDetailCar);
        }
    }
});

