:root {
    --bg-main: #FAF7F2;
    --bg-card: #FFFFFF;
    --bg-dark: #0D3B2E;
    --bg-dark-card: #154A3B;

    --primary: #0D3B2E;
    --primary-hover: #145341;
    --primary-mint: #E8F4EE;
    --accent-gold: #D4AF37;
    --accent-rose: #E5B899;

    --text-primary: #1C2421;
    --text-muted: #5C6662;
    --text-light: #C2D6CE;
    --text-white: #FFFFFF;

    --border-light: rgba(13, 59, 46, 0.1);
    --border-dark: rgba(255, 255, 255, 0.12);

    --font-heading: 'Cormorant Garamond', Georgia, serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;

    --shadow-sm: 0 4px 12px rgba(13, 59, 46, 0.04);
    --shadow-md: 0 12px 32px rgba(13, 59, 46, 0.08);
    --shadow-lg: 0 24px 48px rgba(13, 59, 46, 0.12);

    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 999px;

    --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset & Base */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-main);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    font-weight: 600;
    line-height: 1.2;
}

em {
    font-style: italic;
    color: var(--primary);
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.small-container {
    max-width: 800px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.85rem 1.75rem;
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    border: none;
    cursor: pointer;
    transition: var(--transition);
    text-decoration: none;
}

.btn-emerald {
    background-color: var(--primary);
    color: var(--text-white);
}

.btn-emerald:hover {
    background-color: var(--primary-hover);
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(13, 59, 46, 0.2);
}

.btn-outline {
    background-color: transparent;
    border: 1px solid var(--primary);
    color: var(--primary);
}

.btn-outline:hover {
    background-color: var(--primary-mint);
}

.btn-ghost {
    background: transparent;
    color: var(--text-muted);
}

.btn-ghost:hover {
    color: var(--primary);
}

.btn-full {
    width: 100%;
}

/* Navbar */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 100;
    background: rgba(250, 247, 242, 0.85);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border-light);
    padding: 1rem 0;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary);
    text-decoration: none;
    letter-spacing: 0.05em;
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    text-decoration: none;
    color: var(--text-muted);
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--primary);
}

/* Hero Section */
.hero {
    padding: 9rem 0 5rem;
    overflow: hidden;
}

.hero-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.badge-pill {
    display: inline-block;
    padding: 0.4rem 1rem;
    background-color: var(--primary-mint);
    color: var(--primary);
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    margin-bottom: 1.5rem;
}

.hero-title {
    font-size: 3.8rem;
    color: var(--text-primary);
    margin-bottom: 1.25rem;
    line-height: 1.1;
}

.hero-description {
    font-size: 1.15rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
    max-width: 500px;
}

.hero-email-form {
    display: flex;
    gap: 0.5rem;
    background: var(--bg-card);
    padding: 0.4rem;
    border-radius: var(--radius-full);
    box-shadow: var(--shadow-md);
    border: 1px solid var(--border-light);
    max-width: 500px;
    margin-bottom: 1.5rem;
}

.hero-email-form input {
    flex: 1;
    border: none;
    background: transparent;
    padding: 0 1.25rem;
    font-family: var(--font-body);
    font-size: 0.95rem;
    outline: none;
}

.hero-proof {
    display: flex;
    align-items: center;
    gap: 1rem;
    font-size: 0.85rem;
    color: var(--text-muted);
}

.avatar-group {
    display: flex;
}

.avatar-group img {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: 2px solid var(--bg-main);
    margin-left: -8px;
    object-fit: cover;
}

.avatar-group img:first-child {
    margin-left: 0;
}

/* Hero Visual */
.hero-visual {
    position: relative;
}

.hero-image-wrapper {
    position: relative;
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
}

.hero-main-img {
    width: 100%;
    height: 520px;
    object-fit: cover;
    display: block;
}

.floating-badge {
    position: absolute;
    background: rgba(255, 255, 255, 0.92);
    backdrop-filter: blur(10px);
    padding: 0.85rem 1.25rem;
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-md);
    display: flex;
    align-items: center;
    gap: 0.75rem;
    border: 1px solid rgba(255, 255, 255, 0.5);
    animation: float 4s ease-in-out infinite;
}

.floating-badge.badge-top {
    top: 2rem;
    left: -1.5rem;
}

.floating-badge.badge-bottom {
    bottom: 2rem;
    right: -1.5rem;
    animation-delay: 2s;
}

.floating-badge .icon {
    font-size: 1.5rem;
}

.floating-badge strong {
    display: block;
    font-size: 0.9rem;
    color: var(--text-primary);
}

.floating-badge small {
    font-size: 0.75rem;
    color: var(--text-muted);
}

@keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
}

/* Sections */
.section {
    padding: 6rem 0;
}

.section-header {
    margin-bottom: 3.5rem;
}

.section-header.text-center {
    text-align: center;
}

.section-tag {
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--primary);
    display: block;
    margin-bottom: 0.5rem;
}

.section-header h2 {
    font-size: 2.8rem;
    color: var(--text-primary);
    margin-bottom: 0.75rem;
}

.section-header p {
    font-size: 1.1rem;
    color: var(--text-muted);
    max-width: 600px;
    margin: 0 auto;
}

/* Feature Cards */
.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.feature-card {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    padding: 2.5rem 2rem;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
}

.feature-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-md);
    border-color: rgba(13, 59, 46, 0.2);
}

.feature-card.highlighted {
    border: 2px solid var(--primary);
    background: linear-gradient(180deg, #FFFFFF 0%, #F5FA5F 100%);
}

.card-icon {
    font-size: 2.2rem;
    margin-bottom: 1.25rem;
}

.feature-card h3 {
    font-size: 1.5rem;
    margin-bottom: 0.75rem;
    color: var(--text-primary);
}

.feature-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

/* Principles Grid */
.principles-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
}

.principle-card {
    background: var(--bg-card);
    padding: 2rem;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-light);
}

.principle-card h4 {
    font-size: 1.35rem;
    color: var(--primary);
    margin-bottom: 0.5rem;
}

.principle-card p {
    font-size: 0.9rem;
    color: var(--text-muted);
}

/* How Section (Dark Theme) */
.how-section {
    background-color: var(--bg-dark);
    color: var(--text-white);
}

.dark-text-center {
    text-align: center;
}

.tag-emerald {
    color: var(--accent-gold);
}

.text-white {
    color: var(--text-white);
}

.text-light {
    color: var(--text-light);
}

.steps-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
}

.step-card {
    background: var(--bg-dark-card);
    border: 1px solid var(--border-dark);
    padding: 2.25rem 1.75rem;
    border-radius: var(--radius-md);
    position: relative;
}

.step-number {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--accent-gold);
    opacity: 0.8;
    margin-bottom: 1rem;
}

.step-card h4 {
    font-size: 1.35rem;
    color: var(--text-white);
    margin-bottom: 0.5rem;
}

.step-card p {
    font-size: 0.9rem;
    color: var(--text-light);
}

/* FAQ */
.faq-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.faq-item {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-light);
    overflow: hidden;
}

.faq-question {
    width: 100%;
    padding: 1.5rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: none;
    border: none;
    font-family: var(--font-body);
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    cursor: pointer;
    text-align: left;
}

.faq-answer {
    padding: 0 2rem 1.5rem;
    color: var(--text-muted);
    font-size: 0.95rem;
    display: none;
}

.faq-item.active .faq-answer {
    display: block;
}

/* Footer */
.footer {
    background: #09281F;
    color: var(--text-light);
    padding: 4rem 0 2rem;
    border-top: 1px solid var(--border-dark);
}

.footer-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.footer .logo {
    color: var(--text-white);
    margin-bottom: 0.5rem;
}

.footer-links {
    display: flex;
    gap: 2rem;
}

.footer-links a {
    color: var(--text-light);
    text-decoration: none;
    font-size: 0.9rem;
}

.footer-links a:hover {
    color: var(--text-white);
}

.copyright {
    font-size: 0.8rem;
    opacity: 0.6;
    margin-top: 1rem;
}

/* Modals */
.modal-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(9, 40, 31, 0.7);
    backdrop-filter: blur(8px);
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1.5rem;
    opacity: 0;
    pointer-events: none;
    transition: var(--transition);
}

.modal-backdrop.active {
    opacity: 1;
    pointer-events: auto;
}

.modal-card {
    background: var(--bg-card);
    width: 100%;
    max-width: 560px;
    border-radius: var(--radius-lg);
    padding: 2.5rem;
    box-shadow: var(--shadow-lg);
    position: relative;
    transform: translateY(20px);
    transition: var(--transition);
}

.modal-backdrop.active .modal-card {
    transform: translateY(0);
}

.modal-close {
    position: absolute;
    top: 1.25rem;
    right: 1.25rem;
    background: none;
    border: none;
    font-size: 1.75rem;
    color: var(--text-muted);
    cursor: pointer;
}

.modal-header {
    margin-bottom: 2rem;
}

.modal-header h2 {
    font-size: 2rem;
    color: var(--text-primary);
    margin: 0.5rem 0 0.25rem;
}

.modal-header p {
    font-size: 0.95rem;
    color: var(--text-muted);
}

.form-group {
    margin-bottom: 1.5rem;
}

.form-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 0.4rem;
}

.form-group input, .form-group select, .form-group textarea {
    width: 100%;
    padding: 0.85rem 1.25rem;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-light);
    background: var(--bg-main);
    font-family: var(--font-body);
    font-size: 0.95rem;
    outline: none;
    transition: var(--transition);
}

.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
    border-color: var(--primary);
    background: var(--bg-card);
    box-shadow: 0 0 0 3px rgba(13, 59, 46, 0.1);
}

.chip-group {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.chip-btn {
    padding: 0.5rem 1rem;
    border-radius: var(--radius-full);
    border: 1px solid var(--border-light);
    background: var(--bg-main);
    font-family: var(--font-body);
    font-size: 0.85rem;
    color: var(--text-muted);
    cursor: pointer;
    transition: var(--transition);
}

.chip-btn:hover, .chip-btn.selected {
    background: var(--primary);
    color: var(--text-white);
    border-color: var(--primary);
}

.thank-heart-icon {
    font-size: 3.5rem;
    margin-bottom: 1rem;
}

.waitlist-number-card {
    background: var(--primary-mint);
    padding: 1.5rem;
    border-radius: var(--radius-md);
    margin: 1.5rem 0;
}

.number-label {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--primary);
    display: block;
}

.number-value {
    font-family: var(--font-heading);
    font-size: 2.8rem;
    font-weight: 700;
    color: var(--primary);
}

.share-btns {
    display: flex;
    gap: 0.75rem;
    justify-content: center;
    margin-top: 1rem;
}

/* Responsive */
@media (max-width: 992px) {
    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .hero-description {
        margin: 0 auto 2rem;
    }

    .hero-email-form {
        margin: 0 auto 1.5rem;
    }

    .hero-proof {
        justify-content: center;
    }

    .features-grid, .principles-grid, .steps-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 600px) {
    .nav-links { display: none; }
    .hero-title { font-size: 2.75rem; }
    .features-grid, .principles-grid, .steps-grid { grid-template-columns: 1fr; }
}

// HAVORA Preview Interactions

document.addEventListener('DOMContentLoaded', () => {

    // Modals
    const waitlistModal = document.getElementById('waitlist-modal');
    const researchModal = document.getElementById('research-modal');
    const thankyouModal = document.getElementById('thankyou-modal');

    const openWaitlistBtns = document.querySelectorAll('.open-waitlist-btn');
    const heroEmailForm = document.getElementById('hero-email-form');

    const closeWaitlistBtn = document.getElementById('close-waitlist');
    const closeResearchBtn = document.getElementById('close-research');
    const closeThankyouBtn = document.getElementById('close-thankyou');

    const waitlistForm = document.getElementById('waitlist-form');
    const researchForm = document.getElementById('research-form');

    // Open Waitlist
    openWaitlistBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            waitlistModal.classList.add('active');
        });
    });

    if (heroEmailForm) {
        heroEmailForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const emailInput = heroEmailForm.querySelector('input');
            if (emailInput.value) {
                document.getElementById('email-address').value = emailInput.value;
                waitlistModal.classList.add('active');
            }
        });
    }

    // Close buttons
    closeWaitlistBtn.addEventListener('click', () => waitlistModal.classList.remove('active'));
    closeResearchBtn.addEventListener('click', () => researchModal.classList.remove('active'));
    closeThankyouBtn.addEventListener('click', () => thankyouModal.classList.remove('active'));

    // Step 1 Submit -> Open Step 2
    waitlistForm.addEventListener('submit', (e) => {
        e.preventDefault();
        waitlistModal.classList.remove('active');
        researchModal.classList.add('active');
    });

    // Step 2 Submit -> Open Thank You
    researchForm.addEventListener('submit', (e) => {
        e.preventDefault();
        researchModal.classList.remove('active');
        thankyouModal.classList.add('active');
    });

    // Option Chips Toggle
    const chipBtns = document.querySelectorAll('.chip-btn');
    chipBtns.forEach(chip => {
        chip.addEventListener('click', () => {
            chip.classList.toggle('selected');
        });
    });

    // FAQ Accordion
    const faqItems = document.querySelectorAll('.faq-item');
    faqItems.forEach(item => {
        const questionBtn = item.querySelector('.faq-question');
        questionBtn.addEventListener('click', () => {
            const isActive = item.classList.contains('active');
            faqItems.forEach(el => {
                el.classList.remove('active');
                el.querySelector('.faq-icon').textContent = '+';
            });
            if (!isActive) {
                item.classList.add('active');
                item.querySelector('.faq-icon').textContent = '−';
            }
        });
    });

});

/* ==========================================================================
   HAVORA GLOBAL BRAND SYSTEM — #158265 & #B98D44
   ========================================================================== */

:root {
    --brand-teal: #158265;
    --brand-teal-hover: #116B53;
    --brand-teal-dark: #0A4737;
    --brand-gold: #B98D44;
    --brand-gold-hover: #9E7737;
    --brand-gold-light: #F7F1E5;

    --bg-page: #F8F9F8;
    --bg-card: #FFFFFF;

    --text-dark: #1A2E28;
    --text-muted: #566963;
    --text-white: #FFFFFF;

    --border-subtle: #E2E8E5;

    --font-heading: 'Playfair Display', Georgia, serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, sans-serif;

    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 999px;

    --shadow-card: 0 10px 30px rgba(21, 130, 101, 0.05);
    --shadow-gold: 0 12px 36px rgba(185, 141, 68, 0.15);

    --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Global Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-page);
    color: var(--text-dark);
    line-height: 1.6;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    font-weight: 700;
    line-height: 1.25;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.small-container {
    max-width: 720px;
}

/* Navbar */
.navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    background: #158265; /* Header background as shown in uploaded Figma */
    padding: 1rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    text-decoration: none;
}

.logo-emblem {
    width: 40px;
    height: 40px;
}

.logo-text {
    font-family: var(--font-heading);
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--text-white);
    letter-spacing: 0.02em;
}

.nav-links {
    display: flex;
    gap: 2.2rem;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover, .nav-links a.active {
    color: var(--brand-gold);
    text-decoration: underline;
    text-underline-offset: 6px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    padding: 0.75rem 1.6rem;
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    border: none;
    text-decoration: none;
    cursor: pointer;
    transition: var(--transition);
}

.btn-gold-pill {
    background: var(--bg-card);
    color: var(--brand-teal);
}

.btn-gold-pill:hover {
    background: var(--brand-gold);
    color: var(--text-white);
}

.btn-gold-pill .arrow-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    background: var(--brand-gold);
    color: var(--text-white);
