    color: var(--text-muted);
}

/* Why Havora */
.why-havora-section {
    background: #FFFFFF;
}

.why-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.image-frame {
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-gold);
}

.why-img {
