    margin-bottom: 0.75rem;
}

.why-text-col h2 {
    font-size: 2.4rem;
    margin-bottom: 1.5rem;
    color: var(--text-dark);
}

.why-desc {
    font-size: 1rem;
    color: var(--text-muted);
    margin-bottom: 1.25rem;
}

.why-cta {
    margin-top: 2rem;
}

/* Stands For Grid */
.stands-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.75rem;
    margin-top: 3rem;
}

.stand-card {
    background: var(--bg-card);
    padding: 2.2rem 1.75rem;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-subtle);
}

.stand-card.highlighted-teal {
    background: var(--brand-teal);
    color: var(--text-white);
}

.stand-card.highlighted-teal h3, .stand-card.highlighted-teal p {
    color: var(--text-white);
}

.stand-icon {
    font-size: 2rem;
    margin-bottom: 1rem;
}

.stand-card h3 {
    font-size: 1.35rem;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.stand-card p {
    font-size: 0.9rem;
    color: var(--text-muted);
}

/* How it Works Section (Dark #158265) */
.how-it-works-section {
    background-color: #158265;
    color: var(--text-white);
}

.how-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 3.5rem;
}

.how-card {
    border-left: 2px solid var(--brand-gold);
    padding-left: 1.5rem;
}

.step-num {
    font-family: var(--font-heading);
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--brand-gold);
    margin-bottom: 0.5rem;
}

.how-card h4 {
    font-size: 1.3rem;
    color: var(--text-white);
    margin-bottom: 0.5rem;
}

.how-card p {
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.85);
}

/* FAQ Accordion */
.faq-accordion {
    margin-top: 2.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.faq-item {
    background: var(--bg-card);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-sm);
    overflow: hidden;
}

.faq-trigger {
    width: 100%;
    padding: 1.25rem 1.5rem;
    background: none;
    border: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-body);
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--text-dark);
    cursor: pointer;
    text-align: left;
}

.faq-content {
    padding: 0 1.5rem 1.25rem;
    font-size: 0.95rem;
    color: var(--text-muted);
    display: none;
}

.faq-item.active .faq-content {
    display: block;
}

/* Dedicated Form Pages (Waitlist & Research) */
.main-content {
    padding: 4rem 0 6rem;
    position: relative;
}

.wave-background-svg {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 240px;
    background: linear-gradient(180deg, rgba(21, 130, 101, 0.06) 0%, rgba(248, 249, 248, 0) 100%);
