}

.page-title {
    font-size: 3.2rem;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.page-subtitle {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 2.5rem;
}

.form-wrapper-card {
    background: var(--bg-card);
    padding: 3rem 2.5rem;
