    color: #FFF;
    position: absolute;
    top: -2px;
    left: 4px;
    font-size: 14px;
    font-weight: bold;
}

/* Thank you Page */
.page-thankyou {
    background: #158265;
    color: #FFF;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

.thankyou-card {
