    color: var(--text-dark);
    max-width: 500px;
    width: 100%;
    padding: 3rem 2.5rem;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-gold);
}

.heart-badge-circle {
    width: 64px;
    height: 64px;
    background: rgba(21, 130, 101, 0.1);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.heart-icon {
    width: 36px;
    height: 36px;
}

.thank-title {
    font-size: 2.5rem;
    margin-bottom: 0.75rem;
}

.thank-desc {
    color: var(--text-muted);
    font-size: 1rem;
    margin-bottom: 2rem;
}

.queue-badge {
    background: var(--brand-gold-light);
    border: 1px solid var(--brand-gold);
    padding: 1.25rem;
    border-radius: var(--radius-md);
    margin-bottom: 2rem;
}

.queue-label {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--brand-gold);
    display: block;
}

.queue-number {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--brand-teal);
}

/* Footer */
.footer {
    background: #0D4E3D;
    color: rgba(255, 255, 255, 0.85);
    padding: 4rem 0 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 3rem;
}

.footer-col-brand p {
    font-size: 0.9rem;
    margin: 1rem 0;
    max-width: 300px;
}

.social-icons {
    display: flex;
    gap: 1rem;
}

.social-icons a {
    color: var(--brand-gold);
    text-decoration: none;
    font-weight: bold;
}

.footer-col-links h5 {
    color: #FFF;
    font-size: 1rem;
    margin-bottom: 1rem;
}

.footer-col-links a {
    display: block;
    color: rgba(255, 255, 255, 0.75);
    text-decoration: none;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.footer-col-links a:hover {
    color: var(--brand-gold);
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    margin-top: 3rem;
    padding-top: 1.5rem;
    font-size: 0.8rem;
    color: rgba(255, 255, 255, 0.6);
}

.footer-bottom a {
    color: rgba(255, 255, 255, 0.75);
    text-decoration: none;
}

.link-back-home {
    display: inline-block;
    margin-top: 1rem;
    color: var(--text-muted);
    font-size: 0.9rem;
    text-decoration: none;
}

.link-back-home:hover {
    color: var(--brand-teal);
}

/* Responsive */
@media (max-width: 992px) {
    .hero-title { font-size: 2.8rem; }
    .platform-grid, .stands-grid, .how-grid { grid-template-columns: 1fr 1fr; }
    .why-layout { grid-template-columns: 1fr; }
    .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
    .nav-links { display: none; }
    .hero-title { font-size: 2.2rem; }
    .platform-grid, .stands-grid, .how-grid { grid-template-columns: 1fr; }
}

