// Havora Interactive Script

document.addEventListener('DOMContentLoaded', () => {

    // FAQ Accordion Toggle
    const faqItems = document.querySelectorAll('.faq-item');
    faqItems.forEach(item => {
        const trigger = item.querySelector('.faq-trigger');
        if (trigger) {
            trigger.addEventListener('click', () => {
                const isActive = item.classList.contains('active');
                faqItems.forEach(el => {
                    el.classList.remove('active');
                    const toggle = el.querySelector('.faq-toggle');
                    if (toggle) toggle.textContent = '+';
                });
                if (!isActive) {
                    item.classList.add('active');
                    const toggle = item.querySelector('.faq-toggle');
                    if (toggle) toggle.textContent = '−';
                }
            });
        }
    });

    // Multi-Select Chips Logic (Select up to 3 options)
    const chipBtns = document.querySelectorAll('.chip-option');
    const limitBadge = document.getElementById('limit-badge');
    const hiddenInput = document.getElementById('selected-partner-matters');
    let selectedValues = [];

    if (chipBtns.length > 0) {
        chipBtns.forEach(chip => {
            chip.addEventListener('click', () => {
                const val = chip.getAttribute('data-value');
                const isSelected = chip.classList.contains('selected');

                if (isSelected) {
                    // Unselect
                    chip.classList.remove('selected');
                    selectedValues = selectedValues.filter(item => item !== val);
                } else {
                    // Check limit
                    if (selectedValues.length >= 3) {
                        if (limitBadge) {
                            limitBadge.textContent = "Maximum 3 options reached";
                            limitBadge.classList.add('warning');
                            setTimeout(() => {
                                limitBadge.textContent = "Select up to 3 options";
                                limitBadge.classList.remove('warning');
                            }, 2500);
                        }
                        return;
                    }
                    // Select
                    chip.classList.add('selected');
                    selectedValues.push(val);
                }

                // Update hidden input
                if (hiddenInput) {
                    hiddenInput.value = selectedValues.join(', ');
                }

                // Update badge text counter
                if (limitBadge) {
                    limitBadge.textContent = `${selectedValues.length}/3 Selected`;
                }
            });
        });
    }

});

/* ==========================================================================
   HAVORA GLOBAL BRAND SYSTEM — #158265 & #B98D44
   ========================================================================== */

:root {
    --brand-teal: #158265;
    --brand-teal-hover: #116B53;
    --brand-teal-dark: #0A4737;
    --brand-gold: #B98D44;
    --brand-gold-hover: #9E7737;
    --brand-gold-light: #F7F1E5;

    --bg-page: #F8F9F8;
    --bg-card: #FFFFFF;

    --text-dark: #1A2E28;
    --text-muted: #566963;
    --text-white: #FFFFFF;

    --border-subtle: #E2E8E5;

    --font-heading: 'Playfair Display', Georgia, serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, sans-serif;

    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 999px;

    --shadow-card: 0 10px 30px rgba(21, 130, 101, 0.05);
    --shadow-gold: 0 12px 36px rgba(185, 141, 68, 0.15);

    --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Global Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-page);
    color: var(--text-dark);
    line-height: 1.6;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    font-weight: 700;
    line-height: 1.25;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.small-container {
    max-width: 720px;
}

/* Navbar */
.navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    background: #158265;
    padding: 1rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    text-decoration: none;
}

.logo-emblem {
    width: 40px;
    height: 40px;
}

.logo-text {
    font-family: var(--font-heading);
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--text-white);
    letter-spacing: 0.02em;
}

.nav-links {
    display: flex;
    gap: 2.2rem;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover, .nav-links a.active {
    color: var(--brand-gold);
    text-decoration: underline;
    text-underline-offset: 6px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    padding: 0.75rem 1.6rem;
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    border: none;
    text-decoration: none;
    cursor: pointer;
    transition: var(--transition);
}

.btn-gold-pill {
    background: var(--bg-card);
    color: var(--brand-teal);
}

.btn-gold-pill:hover {
    background: var(--brand-gold);
    color: var(--text-white);
}

.btn-gold-pill .arrow-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    background: var(--brand-gold);
    color: var(--text-white);
    border-radius: 50%;
    font-size: 0.85rem;
}

.btn-gold-lg {
    background: var(--bg-card);
    color: var(--brand-teal);
    padding: 1rem 2.2rem;
    font-size: 1.1rem;
    font-weight: 700;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}

.btn-gold-lg:hover {
    background: var(--brand-gold);
    color: var(--text-white);
    transform: translateY(-2px);
}

.btn-gold-lg .arrow-circle-lg {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: var(--brand-gold);
    color: var(--text-white);
    border-radius: 50%;
    font-size: 1rem;
}

.btn-teal {
    background: var(--brand-teal);
    color: var(--text-white);
}

.btn-teal:hover {
    background: var(--brand-teal-hover);
}

.btn-teal-filled {
    background: var(--brand-teal);
    color: var(--text-white);
    padding: 0.9rem 2rem;
    font-size: 1rem;
}

.btn-teal-filled:hover {
    background: var(--brand-teal-hover);
}

.btn-outline-gold {
    background: transparent;
    border: 2px solid var(--brand-teal);
    color: var(--brand-teal);
    padding: 0.9rem 2rem;
    border-radius: var(--radius-full);
}

.btn-outline-gold:hover {
    background: var(--brand-teal);
    color: var(--text-white);
}

.btn-full {
    width: 100%;
}

/* Hero Banner (Clean, Overlay Removed) */
.hero-banner {
    position: relative;
    min-height: 540px;
    background: url('https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-white);
    padding: 5rem 1.5rem;
}

.hero-container {
    position: relative;
    z-index: 2;
    max-width: 900px;
}

.hero-title {
    font-size: 3.8rem;
    line-height: 1.15;
    margin-bottom: 1.5rem;
    text-shadow: 0 4px 12px rgba(0, 0, 0, 0.4);
}

.highlight-gold {
