/* FAQ Accordion */
.faq-accordion {
    margin-top: 2.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.faq-item {
    background: var(--bg-card);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-sm);
    overflow: hidden;
}

.faq-trigger {
    width: 100%;
    padding: 1.25rem 1.5rem;
    background: none;
    border: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-body);
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--text-dark);
    cursor: pointer;
    text-align: left;
}

.faq-content {
    padding: 0 1.5rem 1.25rem;
    font-size: 0.95rem;
    color: var(--text-muted);
    display: none;
}

.faq-item.active .faq-content {
    display: block;
}

/* Dedicated Form Pages (Waitlist & Research) */
.main-content {
    padding: 4rem 0 6rem;
    position: relative;
}

.wave-background-svg {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 240px;
    background: linear-gradient(180deg, rgba(21, 130, 101, 0.06) 0%, rgba(248, 249, 248, 0) 100%);
    z-index: -1;
}

.page-title {
    font-size: 3.2rem;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.page-subtitle {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 2.5rem;
}

.form-wrapper-card {
    background: var(--bg-card);
    padding: 3rem 2.5rem;
    border-radius: var(--radius-lg);
    border: 1px solid var(--border-subtle);
    box-shadow: var(--shadow-card);
}

.form-group {
    margin-bottom: 1.75rem;
}

.form-group label {
    display: block;
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.label-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.optional-tag {
    font-size: 0.85rem;
    color: var(--text-muted);
    font-weight: 400;
}

.form-group input, .form-group select, .form-group textarea {
    width: 100%;
    padding: 0.95rem 1.25rem;
    border-radius: var(--radius-sm);
    border: 1px solid #D0DAD5;
    background: #FFFFFF;
    font-family: var(--font-body);
    font-size: 0.95rem;
    outline: none;
    transition: var(--transition);
}

.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
    border-color: var(--brand-teal);
    box-shadow: 0 0 0 3px rgba(21, 130, 101, 0.12);
}

/* Checkbox */
.form-checkbox-group {
    margin: 2rem 0;
}

.checkbox-container {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.9rem;
    color: var(--text-muted);
}

.checkbox-container input {
    display: none;
}

.checkmark {
    width: 20px;
    height: 20px;
    background: #FFFFFF;
    border: 2px solid var(--brand-teal);
    border-radius: 4px;
    flex-shrink: 0;
    position: relative;
}

.checkbox-container input:checked ~ .checkmark {
    background: var(--brand-teal);
}

.checkbox-container input:checked ~ .checkmark::after {
    content: "✓";
    color: #FFF;
    position: absolute;
    top: -2px;
    left: 4px;
    font-size: 14px;
    font-weight: bold;
}

/* Thank you Page */
.page-thankyou {
    background: #158265;
    color: #FFF;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

.thankyou-card {
    background: #FFFFFF;
    color: var(--text-dark);
    max-width: 500px;
    width: 100%;
    padding: 3rem 2.5rem;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-gold);
}

.heart-badge-circle {
    width: 64px;
    height: 64px;
    background: rgba(21, 130, 101, 0.1);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.heart-icon {
    width: 36px;
    height: 36px;
}

.thank-title {
    font-size: 2.5rem;
    margin-bottom: 0.75rem;
}

.thank-desc {
    color: var(--text-muted);
    font-size: 1rem;
    margin-bottom: 2rem;
}

.queue-badge {
    background: var(--brand-gold-light);
    border: 1px solid var(--brand-gold);
    padding: 1.25rem;
    border-radius: var(--radius-md);
    margin-bottom: 2rem;
}

.queue-label {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--brand-gold);
    display: block;
}

.queue-number {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--brand-teal);
}

/* Footer — Same Shade #158265 as Navbar */
.footer {
    background: #158265;
    color: rgba(255, 255, 255, 0.95);
    padding: 4rem 0 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.15);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 3rem;
}

.footer-col-brand p {
    font-size: 0.9rem;
    margin: 1rem 0;
    max-width: 300px;
    color: rgba(255, 255, 255, 0.9);
}

.social-icons {
    display: flex;
    gap: 1rem;
}

.social-icons a {
    color: var(--brand-gold);
    text-decoration: none;
    font-weight: bold;
}

.footer-col-links h5 {
    color: #FFF;
    font-size: 1rem;
    margin-bottom: 1rem;
}

.footer-col-links a {
    display: block;
    color: rgba(255, 255, 255, 0.85);
    text-decoration: none;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.footer-col-links a:hover {
    color: var(--brand-gold);
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.15);
    margin-top: 3rem;
    padding-top: 1.5rem;
    font-size: 0.8rem;
    color: rgba(255, 255, 255, 0.75);
}

.footer-bottom a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
}

.link-back-home {
    display: inline-block;
    margin-top: 1rem;
    color: var(--text-muted);
    font-size: 0.9rem;
    text-decoration: none;
}

.link-back-home:hover {
    color: var(--brand-teal);
}

/* Responsive */
@media (max-width: 992px) {
    .hero-title { font-size: 2.8rem; }
    .platform-grid, .stands-grid, .how-grid { grid-template-columns: 1fr 1fr; }
    .why-layout { grid-template-columns: 1fr; }
    .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
    .nav-links { display: none; }
    .hero-title { font-size: 2.2rem; }
    .platform-grid, .stands-grid, .how-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   HAVORA GLOBAL BRAND SYSTEM — #158265 & #B98D44
   ========================================================================== */

:root {
    --brand-teal: #158265;
    --brand-teal-hover: #116B53;
    --brand-teal-dark: #0D4E3D;
    --brand-gold: #B98D44;
    --brand-gold-hover: #9E7737;
    --brand-gold-light: #F7F1E5;

    --bg-page: #F8F9F8;
    --bg-card: #FFFFFF;

    --text-dark: #1A2E28;
    --text-muted: #566963;
    --text-white: #FFFFFF;

    --border-subtle: #E2E8E5;

    --font-heading: 'Playfair Display', Georgia, serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, sans-serif;

    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 999px;

    --shadow-card: 0 10px 30px rgba(21, 130, 101, 0.05);
    --shadow-gold: 0 12px 36px rgba(185, 141, 68, 0.15);

    --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Global Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-page);
    color: var(--text-dark);
    line-height: 1.6;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    font-weight: 700;
    line-height: 1.25;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.small-container {
    max-width: 720px;
}

/* Navbar — Shade #158265 */
.navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    background: #158265;
    padding: 1rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    text-decoration: none;
}

.logo-emblem {
    width: 40px;
    height: 40px;
}

.logo-text {
    font-family: var(--font-heading);
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--text-white);
    letter-spacing: 0.02em;
}

.nav-links {
    display: flex;
    gap: 2.2rem;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover, .nav-links a.active {
    color: var(--brand-gold);
    text-decoration: underline;
    text-underline-offset: 6px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    padding: 0.75rem 1.6rem;
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    border: none;
    text-decoration: none;
    cursor: pointer;
    transition: var(--transition);
}

.btn-gold-pill {
    background: var(--bg-card);
    color: var(--brand-teal);
}

.btn-gold-pill:hover {
    background: var(--brand-gold);
    color: var(--text-white);
}

.btn-gold-pill .arrow-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    background: var(--brand-gold);
    color: var(--text-white);
    border-radius: 50%;
    font-size: 0.85rem;
}

.btn-gold-lg {
    background: var(--bg-card);
    color: var(--brand-teal);
    padding: 1rem 2.2rem;
    font-size: 1.1rem;
    font-weight: 700;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}

.btn-gold-lg:hover {
    background: var(--brand-gold);
    color: var(--text-white);
    transform: translateY(-2px);
}

.btn-gold-lg .arrow-circle-lg {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: var(--brand-gold);
    color: var(--text-white);
    border-radius: 50%;
    font-size: 1rem;
}

.btn-teal {
    background: var(--brand-teal);
    color: var(--text-white);
}

.btn-teal:hover {
    background: var(--brand-teal-hover);
}

.btn-teal-filled {
    background: var(--brand-teal);
    color: var(--text-white);
    padding: 0.9rem 2rem;
    font-size: 1rem;
}

.btn-teal-filled:hover {
    background: var(--brand-teal-hover);
}

.btn-outline-gold {
    background: transparent;
    border: 2px solid var(--brand-teal);
    color: var(--brand-teal);
    padding: 0.9rem 2rem;
    border-radius: var(--radius-full);
}

.btn-outline-gold:hover {
    background: var(--brand-teal);
    color: var(--text-white);
}

.btn-full {
    width: 100%;
}

/* Hero Banner (Clean, Overlay Removed) */
.hero-banner {
    position: relative;
    min-height: 540px;
    background: url('https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-white);
    padding: 5rem 1.5rem;
}

.hero-container {
    position: relative;
    z-index: 2;
    max-width: 900px;
}

.hero-title {
    font-size: 3.8rem;
    line-height: 1.15;
    margin-bottom: 1.5rem;
    text-shadow: 0 4px 12px rgba(0, 0, 0, 0.4);
}

.highlight-gold {
    color: var(--brand-gold);
}

.hero-subtext {
    font-size: 1.25rem;
    color: rgba(255, 255, 255, 0.98);
    max-width: 720px;
    margin: 0 auto 2.5rem;
    font-weight: 500;
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

/* Multi-Select Option Chips for Partner Preferences */
.multiselect-chip-container {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    margin-top: 0.75rem;
}

.chip-option {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.65rem 1.1rem;
    border-radius: var(--radius-full);
    border: 1.5px solid #D0DAD5;
    background: #FFFFFF;
    font-family: var(--font-body);
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-dark);
    cursor: pointer;
    transition: var(--transition);
}

.chip-option .chip-check {
    display: none;
    font-weight: bold;
}

.chip-option:hover {
    border-color: var(--brand-teal);
    background: rgba(21, 130, 101, 0.05);
}

.chip-option.selected {
    background: var(--brand-teal);
    color: #FFFFFF;
    border-color: var(--brand-gold);
    font-weight: 600;
}

.chip-option.selected .chip-check {
    display: inline;
    color: var(--brand-gold);
}

.select-limit-badge {
    font-size: 0.85rem;
    color: var(--brand-gold);
    font-weight: 600;
    background: var(--brand-gold-light);
    padding: 0.2rem 0.6rem;
    border-radius: var(--radius-sm);
    transition: var(--transition);
}

.select-limit-badge.warning {
    color: #D9534F;
    background: #FDF7F7;
}

/* Sections */
.section {
    padding: 5rem 0;
}

.section-header h2 {
    font-size: 2.5rem;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.section-header p {
    font-size: 1.05rem;
    color: var(--text-muted);
}

.text-center { text-align: center; }
.text-white { color: var(--text-white) !important; }
.text-gold { color: var(--brand-gold) !important; }

/* Platform Cards */
.platform-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 3rem;
}

.platform-card {
    background: var(--bg-card);
    padding: 2.5rem 2rem;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-subtle);
    box-shadow: var(--shadow-card);
    transition: var(--transition);
}

.platform-card:hover {
    transform: translateY(-4px);
    border-color: var(--brand-teal);
}

.card-icon-badge {
    width: 48px;
    height: 48px;
    background: rgba(21, 130, 101, 0.1);
    color: var(--brand-teal);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1.25rem;
}

.card-icon-badge .icon {
    width: 28px;
    height: 28px;
}

.platform-card h3 {
    font-size: 1.4rem;
    color: var(--brand-teal);
    margin-bottom: 0.75rem;
}

.platform-card p {
    font-size: 0.95rem;
    color: var(--text-muted);
}

/* Why Havora */
