    background: #FFFFFF;
}

.why-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.image-frame {
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-gold);
}

.why-img {
    width: 100%;
    height: 480px;
    object-fit: cover;
    display: block;
}

.why-tag-gold {
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--brand-gold);
    display: block;
    margin-bottom: 0.75rem;
}

.why-text-col h2 {
    font-size: 2.4rem;
