/* ==========================================================================
   HAVORA v2 DESIGN SYSTEM — BOOTSTRAP 5.3 + BRAND COLORS #158265 & #B98D44
   ========================================================================== */

:root {
    --brand-teal: #158265;
    --brand-teal-hover: #116B53;
    --brand-teal-dark: #0D4E3D;
    --brand-gold: #B98D44;
    --brand-gold-hover: #9E7737;
    --brand-gold-light: #F7F1E5;

    --bg-page: #F8F9F8;
    --bg-card: #FFFFFF;

    --text-dark: #1A2E28;
    --text-muted: #566963;
    --text-white: #FFFFFF;

    --border-subtle: #E2E8E5;

    --font-heading: 'Playfair Display', Georgia, serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, sans-serif;

    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 999px;

    --shadow-card: 0 10px 30px rgba(21, 130, 101, 0.05);
    --shadow-gold: 0 12px 36px rgba(185, 141, 68, 0.15);

    --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Global Reset */
body {
    font-family: var(--font-body);
    background-color: var(--bg-page);
    color: var(--text-dark);
    line-height: 1.6;
}

h1, h2, h3, h4, .font-heading {
    font-family: var(--font-heading);
}

/* Custom Navbar */
.custom-navbar {
    background-color: #158265 !important;
    padding: 0.85rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}

.logo-emblem {
    width: 38px;
    height: 38px;
}

.nav-links .nav-link {
    color: rgba(255, 255, 255, 0.9) !important;
    font-weight: 500;
    margin: 0 0.5rem;
    transition: var(--transition);
}

.nav-links .nav-link:hover, .nav-links .nav-link.active {
    color: var(--brand-gold) !important;
    text-decoration: underline;
    text-underline-offset: 6px;
}

.navbar-toggler-icon-custom {
    color: var(--brand-gold);
    font-size: 1.5rem;
}

/* Buttons */
.btn-gold-pill {
    background: #FFFFFF;
    color: var(--brand-teal);
    font-weight: 600;
    border-radius: var(--radius-full);
    padding: 0.6rem 1.4rem;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: var(--transition);
}

.btn-gold-pill:hover {
    background: var(--brand-gold);
    color: #FFFFFF;
}

.btn-gold-pill .arrow-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    background: var(--brand-gold);
    color: #FFFFFF;
    border-radius: 50%;
    font-size: 0.8rem;
}

.btn-gold-lg {
    background: #FFFFFF;
    color: var(--brand-teal);
    padding: 0.9rem 2rem;
    font-size: 1.1rem;
    font-weight: 700;
    border-radius: var(--radius-full);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
    transition: var(--transition);
}

.btn-gold-lg:hover {
    background: var(--brand-gold);
    color: #FFFFFF;
    transform: translateY(-2px);
}

.btn-gold-lg .arrow-circle-lg {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    background: var(--brand-gold);
    color: #FFFFFF;
    border-radius: 50%;
    font-size: 0.95rem;
}

.btn-teal {
    background: var(--brand-teal);
    color: #FFFFFF;
    padding: 0.8rem 1.8rem;
    border-radius: var(--radius-full);
    text-decoration: none;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: var(--transition);
}

.btn-teal:hover {
    background: var(--brand-teal-hover);
    color: #FFFFFF;
}

.btn-teal-filled {
    background: var(--brand-teal);
    color: #FFFFFF;
    padding: 0.9rem 2rem;
    border-radius: var(--radius-full);
    border: none;
    font-weight: 600;
}

.btn-teal-filled:hover {
    background: var(--brand-teal-hover);
    color: #FFFFFF;
}

.btn-outline-gold {
    background: transparent;
    border: 2px solid var(--brand-teal);
    color: var(--brand-teal);
    padding: 0.9rem 2rem;
    border-radius: var(--radius-full);
    font-weight: 600;
}

.btn-outline-gold:hover {
    background: var(--brand-teal);
    color: #FFFFFF;
}

/* Hero Carousel (3 Slides) */
.hero-carousel {
    min-height: 580px;
    background: #000000;
}

.hero-carousel .carousel-item {
    height: 580px;
    background-size: cover;
    background-position: center 30%;
    position: relative;
}

.hero-slide-bg-1 {
    background-image: url('hero-banner.jpg');
}

.hero-slide-bg-2 {
    background-image: url('https://images.unsplash.com/photo-1522529599102-193c0d76b5b6?auto=format&fit=crop&w=1600&q=80');
}

.hero-slide-bg-3 {
    background-image: url('why-havora.jpg');
}

.hero-caption {
    top: 50%;
    transform: translateY(-50%);
    bottom: auto;
    left: 0;
    right: 0;
    padding: 0 1.5rem;
}

.hero-title {
    font-size: 3.6rem;
    font-weight: 700;
    line-height: 1.15;
    text-shadow: 0 4px 16px rgba(0, 0, 0, 0.7);
}

.highlight-gold {
    color: var(--brand-gold);
}

.hero-subtext {
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.95);
    max-width: 700px;
    text-shadow: 0 2px 10px rgba(0, 0, 0, 0.7);
}

.carousel-indicators [data-bs-target] {
    width: 32px;
    height: 4px;
    border-radius: 2px;
    background-color: var(--brand-gold);
}

/* Cards & Components */
.platform-card {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-subtle);
    box-shadow: var(--shadow-card);
    transition: var(--transition);
}

.platform-card:hover {
    transform: translateY(-4px);
    border-color: var(--brand-teal);
}

.card-icon-badge {
    width: 48px;
    height: 48px;
    background: rgba(21, 130, 101, 0.1);
    color: var(--brand-teal);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
}

.card-icon-badge .icon {
    width: 26px;
    height: 26px;
}

.why-tag-gold {
    color: var(--brand-gold);
    letter-spacing: 0.08em;
    font-size: 0.85rem;
}

.shadow-gold {
    box-shadow: var(--shadow-gold);
}

.stand-card {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-subtle);
}

.stand-card.highlighted-teal {
    background: var(--brand-teal);
    color: #FFFFFF;
}

.stand-card.highlighted-teal h3, .stand-card.highlighted-teal p {
    color: #FFFFFF !important;
}

.how-it-works-section {
    background-color: #0D4E3D;
}

.text-gold {
    color: var(--brand-gold) !important;
}

.how-card {
    border-left: 2px solid var(--brand-gold);
    padding-left: 1.25rem;
}

.step-num {
    font-family: var(--font-heading);
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--brand-gold);
}

/* Dedicated Form Pages */
.form-wrapper-card {
    background: var(--bg-card);
    border-radius: var(--radius-lg);
    border: 1px solid var(--border-subtle);
    box-shadow: var(--shadow-card);
}

.multiselect-chip-container {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    margin-top: 0.75rem;
}

.chip-option {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.65rem 1.1rem;
    border-radius: var(--radius-full);
    border: 1.5px solid #D0DAD5;
    background: #FFFFFF;
    font-family: var(--font-body);
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-dark);
    cursor: pointer;
    transition: var(--transition);
}

.chip-option .chip-check {
    display: none;
    font-weight: bold;
}

.chip-option:hover {
    border-color: var(--brand-teal);
    background: rgba(21, 130, 101, 0.05);
}

.chip-option.selected {
    background: var(--brand-teal);
    color: #FFFFFF;
    border-color: var(--brand-gold);
    font-weight: 600;
}

.chip-option.selected .chip-check {
    display: inline;
    color: var(--brand-gold);
}

.select-limit-badge {
    font-size: 0.85rem;
    color: var(--brand-gold);
    font-weight: 600;
    background: var(--brand-gold-light);
    padding: 0.2rem 0.6rem;
    border-radius: var(--radius-sm);
    transition: var(--transition);
}

/* Thank You Page */
.page-thankyou {
    background: #158265;
    min-height: 100vh;
}

.thankyou-card {
    background: #FFFFFF;
    max-width: 500px;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-gold);
}

.heart-badge-circle {
    width: 64px;
    height: 64px;
    background: rgba(21, 130, 101, 0.1);
    border-radius: 50%;
    margin: 0 auto 1.5rem;
}

.heart-icon {
    width: 36px;
    height: 36px;
}

.queue-badge {
    background: var(--brand-gold-light);
    border: 1px solid var(--brand-gold);
    padding: 1.25rem;
    border-radius: var(--radius-md);
}

.queue-label {
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--brand-gold);
}

.queue-number {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--brand-teal);
}

/* Footer — Same #158265 as Navbar */
.footer {
    background-color: #158265 !important;
}

/* Custom Checkbox */
.checkbox-container {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.9rem;
    color: var(--text-muted);
}

.checkbox-container input {
    display: none;
}

.checkmark {
    width: 20px;
    height: 20px;
    background: #FFFFFF;
    border: 2px solid var(--brand-teal);
    border-radius: 4px;
    flex-shrink: 0;
    position: relative;
}

.checkbox-container input:checked ~ .checkmark {
    background: var(--brand-teal);
}

.checkbox-container input:checked ~ .checkmark::after {
    content: "✓";
    color: #FFF;
    position: absolute;
    top: -2px;
    left: 4px;
    font-size: 14px;
    font-weight: bold;
}

/* Responsive Overrides */
@media (max-width: 992px) {
    .hero-title { font-size: 2.6rem; }
    .hero-carousel .carousel-item { height: 480px; }
}

@media (max-width: 576px) {
    .hero-title { font-size: 2rem; }
    .hero-subtext { font-size: 1rem; }
    .hero-carousel .carousel-item { height: 420px; }
}

